-- Run in Supabase SQL Editor. Keep service-role credentials server-side.
create table if not exists public.api_key_requests (id bigint generated by default as identity primary key, name text not null, email text not null, reason text default '', status text not null default 'pending' check(status in ('pending','approved','rejected','issued')), api_key_id bigint, key_encrypted text, key_delivered boolean not null default false, created_at timestamptz not null default now());
create table if not exists public.api_keys (id bigint generated by default as identity primary key, label text not null, owner_email text not null, key_hash text not null unique, key_prefix text not null, revoked boolean not null default false, created_at timestamptz not null default now(), revoked_at timestamptz, expires_at timestamptz);
create table if not exists public.short_urls (id bigint generated by default as identity primary key, code varchar(12) not null unique, original_url text not null, api_key_id bigint not null references public.api_keys(id), created_at timestamptz not null default now(), clicks bigint not null default 0);
create index if not exists idx_short_urls_code on public.short_urls(code);
create index if not exists idx_short_urls_key on public.short_urls(api_key_id);
create index if not exists idx_api_keys_hash on public.api_keys(key_hash);

-- Migration for an existing database created with an older version of this MVP.
alter table public.api_key_requests alter column status set default 'pending';
alter table public.api_key_requests add column if not exists api_key_id bigint;
alter table public.api_key_requests add column if not exists key_encrypted text;
alter table public.api_key_requests add column if not exists key_delivered boolean not null default false;
alter table public.api_key_requests drop constraint if exists api_key_requests_status_check;
alter table public.api_key_requests add constraint api_key_requests_status_check check (status in ('pending','approved','rejected','issued'));

-- Optional key expiry support for existing installations.
alter table public.api_keys add column if not exists expires_at timestamptz;
